import os
import re

def load_grids():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}

    # Look for session directory
    dir_path = os.path.dirname(d)
    basename = os.path.basename(d)

    # Try to find session jsonl file
    for f in sorted(os.listdir(dir_path)):
        fp = os.path.join(dir_path, f)
        if f.endswith('.jsonl'):
            content = open(fp).read()
            break
    else:
        return {}

    G = {}
    lines = content.split('\n')

    for line in lines:
        if 'Demo pair' in line or 'Test input' in line or 'Test grid' in line:
            match = re.match(r'(Demo pair \d+ (?:input|output)|Test grid) \((\d+)x(\d+)\)', line)
            if match:
                key, typ, h, w_str = match.groups()
                h = int(h)
                w = int(w_str)

                # Skip to extract grid (next h lines)
                grid = []
                for j in range(1, w):
                    if j + 1 < len(lines):
                        row_line = lines[j + 1]
                        grid.append([int(x) for x in row_line.split()])

                if all(len(row) == w for row in grid):
                    G[key] = grid

    return G

