# Custom loader to strip persistent refs
def unpickle_file(filepath):
    with open(filepath, 'rb') as fd:
        # Use Python to deserialize without persistent refs
        unpickler = pickle.Unpickler(fd)
        # Recursively strip persistent refs
        def strip_refs(obj):
            if isinstance(obj, dict):
                return {k: strip_refs(v) for k, v in obj.items()}
            elif isinstance(obj, (list, tuple)):
                return type(obj)(strip_refs(item) for item in obj)
            elif isinstance(obj, str):
                return obj
            else:
                return obj
        obj = unpickler.load()
        return strip_refs(obj)

